local cs_coroutine = import('XLua.cs_coroutine')
local WaitForSeconds = CS.UnityEngine.WaitForSeconds
local UIModule = CS.Engine.UI.UIModule
local KTool = CS.Engine.Lib.KTool
local worldBossComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.WorldBossComponent)

---@class WorldBossPlayerRankService
local WorldBossPlayerRankService = Class("WorldBossPlayerRankService")

function WorldBossPlayerRankService.new(facade)
    local obj = WorldBossPlayerRankService.New()
    obj.facade = facade
    obj.CoOpenPanel = nil
    obj.panelGo = nil
    obj.panelCtrl = nil
    obj.rankListData = {
        prefabPath = "Prefabs/WorldBoss/WorldBossPlayerRankingsDialog.prefab",
        srcPath = "Game.UI.FightReady.UIWorldBoss.UIWorldBossPlayerRankingsDialog.UIWorldBossPlayerRankingsDialog"
    }
    return obj
end

function WorldBossPlayerRankService:UpdateInfo()
    self:Dispose()
    self.CoOpenPanel = cs_coroutine.start(function()
        self.panelGo = GameUtils.LoadBundleAsync(self.rankListData.prefabPath, self.facade.controller.gameObject, false)
        if not self.panelGo then return end
        self.panelCtrl = CfUtils.GetLuaScr(self.panelGo, self.rankListData.srcPath)

        local isOpen = worldBossComponent:IsOpen()
        if not isOpen then
            KTool.SetActive(self.panelCtrl.EmptyNode, true)
            return
        end

        local rankInfoData = {}

        GameUtils.Request(Interfaces.WorldBossRank, {}, function(request, response)
            if checkNumber(response.errCode) ~= 0 then
                GameUtils.Toast(localize("请求失败"))
                return
            end

            local RankingListDojo = import("Game.Dojo.RankingListDojo")

            local jsonData = response.data
            local rankInfo = jsonData.rankInfo
            local t = {}
            for k, v in pairs(rankInfo) do
                local dojo = RankingListDojo.New()
                dojo:Fill(v)
                dojo.rankNum = checkNumber(k)
                table.insert(t, dojo)
            end

            rankInfoData.rankList = t

            rankInfoData.playerRank = worldBossComponent:GetCurRankInfo()

            rankInfoData.percentageRank = checkNumber(jsonData.percentageRank)
            self.panelCtrl:UpdateInfo(rankInfoData)

            self.CoOpenPanel = nil
        end)
    end)
    return self.CoOpenPanel
end

function WorldBossPlayerRankService:Dispose()
    if not isNull(self.CoOpenPanel) then
        cs_coroutine.stop(self.CoOpenPanel)
        self.CoOpenPanel = nil
    end
    if self.panelGo then
        KTool.SafeDelete(self.panelGo)
    end
end

return WorldBossPlayerRankService